#pragma once
#include <stdint.h>
#include "fork_forms.h"

// Adventures: a five-stage raid run with a loan creature, a boss, and one
// creature kept at the end. android/FEATURES_PLAN.md, Phase 12. Fork-only:
// nothing here runs unless forkFeatures() is on, and the board never sees it.
//
// This file is the mode's home. Step 12a (forms) lives here first; the battle,
// the run and the companions follow it.

// --- 12a. forms -------------------------------------------------------------
//
// FORM_TBL (fork_forms.h, generated by tools/gen_forms.py) holds every Mega,
// Primal, G-Max, Ultra Burst and fusion with known stats -- INCLUDING ones with
// no sprite, so that a form keeps its persisted id when upstream draws it.
// A form with no art must never be offered, so every caller asks these rather
// than reading FORM_TBL[].art itself (CLAUDE.md trap 1: one rule, one function).

// The row for a form id, or nullptr for 0 / out of range.
const FormEntry *forkForm(uint8_t id);
// Can this form be shown and spawned: a real row with art.
bool forkFormUsable(uint8_t id);
// The usable forms of one species, FK_NONE meaning every kind. Writes up to
// `max` ids into `out` (which may be null to just count) and returns how many
// there are in all.
uint8_t forkFormsOf(int16_t dex, uint8_t kind, uint8_t *out, uint8_t max);
// A battle STATE (Mega, Primal, G-Max, Ultra) rather than a creature of its
// own: kept as permission to transform, never as the creature's form.
bool forkFormIsState(uint8_t kind);
